using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: EF Core 9 renamed the default discriminator property
            // from "Discriminator" to "$type". Preserve "Discriminator" so existing 500K
            // documents remain readable and direct SQL queries
            // (WHERE c.Discriminator = 'Product') keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed the default Cosmos JSON `id` format
            // from "EntityType|Key" (e.g. "Product|123") to just the key value ("123").
            // Existing documents use the old format, so we must preserve it.
            // We add an explicit shadow property mapped to the JSON "id" field.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // BREAKING CHANGE 3: HasIndex() now throws for the Cosmos provider because
            // Cosmos DB does not support traditional indexes. Removed the HasIndex call.
        });
    }
}

